const RTFlow=(()=>{
 const statuses={new:{label:'尚未跟进',en:'Not started'},follow:{label:'跟进中',en:'Following up'},hold:{label:'On hold · 暂缓',en:'On hold'},giveup:{label:'Give up · 放弃',en:'Give up'},client:{label:'已合作',en:'Client'},excluded:{label:'Delisted',en:'Excluded'}};
 const status=l=>RTCRM.visible(l)?RTCRM.get(l.id).status:'excluded';
 const badge=l=>`<span class="stage stage-${status(l)}">${statuses[status(l)]?.label||statuses.new.label}</span>`;
 const pair=p=>`<div class="bilingual"><div lang="zh-CN"><p>${esc(p?.zh||'待核实')}</p></div><div lang="en"><p>${esc(p?.en||'To verify')}</p></div></div>`;
 function summary(l){return `<div class="summary-metrics"><span>${badge(l)}</span><span>${RTCRM.star(l.id)}</span></div><div class="summary-grid">${(l.profile_summary||[]).map(x=>`<article><h4>${esc(x.title.zh)} / ${esc(x.title.en)}</h4>${pair(x.body)}</article>`).join('')}</div>`}
 function schedules(l){const slots=RTCRM.slots(l.id);return `<section class="schedule-editor"><h3>固定档期 / Recurring slots</h3><div>${slots.map((s,i)=>`<div class="slot-row"><span>${['周日','周一','周二','周三','周四','周五','周六'][s.weekday]} ${esc(s.start)}–${esc(s.end)} · ${s.courts} 场 <small>${esc(s.from)} → ${esc(s.until||'持续')}</small></span>${RTCRM.canEdit?`<button type="button" data-delete-slot="${i}">移除</button>`:''}</div>`).join('')||'<p>暂无固定档期</p>'}</div>${RTCRM.canEdit?`<form id="slot-form"><label>每周<select name="weekday">${['周日','周一','周二','周三','周四','周五','周六'].map((d,i)=>`<option value="${i}">${d}</option>`).join('')}</select></label><label>开始时间<input type="time" name="start" required></label><label>结束时间<input type="time" name="end" required></label><label>场数<input type="number" name="courts" min="1" max="100" value="1" required></label><label>生效日期<input type="date" name="from" required></label><label>截止日期<input type="date" name="until"></label><button>添加档期</button><span id="slot-message" role="status"></span></form>`:''}</section>`}
 function actions(l,detail=false){const st=status(l);if(!RTCRM.canEdit)return `<div class="row-actions"><a class="button" href="${RTSales.signIn()}" target="_top">登录编辑 / Sign in to edit</a>${detail?'<small>'+ (RTCRM.authState==='wrong-account'?'当前账户没有编辑权限，请使用管理账户。':'当前为只读浏览。')+'</small>':''}</div>`;
 const primary=st==='client'?`<button data-sales="payment" data-lead="${esc(l.id)}">Make a Payment</button><button data-sales="order" data-lead="${esc(l.id)}">Make an Order</button>`:`<div class="split-action"><button data-stage="${st!=='new'?'client':'follow'}" data-lead="${esc(l.id)}">${st!=='new'?'Mark as Client':'Followup'}</button><details><summary aria-label="更多推进状态">▾</summary><div class="action-menu">${['hold','giveup'].includes(st)?`<button data-stage="follow" data-lead="${esc(l.id)}">恢复跟进 / Resume</button>`:''}<button data-stage="hold" data-lead="${esc(l.id)}">On hold · 暂缓</button><button data-stage="giveup" data-lead="${esc(l.id)}">Give up · 放弃</button></div></details></div>`;
 return `<div class="row-actions">${primary}<button data-detail-action="${esc(l.id)}">Detail</button><details class="more-action"><summary>More</summary><div class="action-menu"><button data-misleading="${esc(l.id)}">🗑 Report as Misleading</button></div></details></div>`}
 async function stage(id,value){const l=leads.find(x=>x.id===id);if(!l)return;if(value==='client'&&!confirm('确认此客户已签约并正式付款？ / Confirm signed and paid?'))return;
 try{if(detailDirty&&$('detail').dataset.id===id){const m=RTCRM.get(id);await RTCRM.save(id,{level:+$('edit-level').value,note:$('edit-note').value,action:$('edit-action').value,follow:m.status==='follow'});detailDirty=false}await RTCRM.changeStatus(id,value,value==='client');render();if($('detail').open)openDetail(id)}catch(e){alert(e.message)}}
 function bindActions(){document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=async()=>{b.disabled=true;await stage(b.dataset.lead,b.dataset.stage);b.disabled=false});document.querySelectorAll('[data-detail-action]').forEach(b=>b.onclick=()=>{state.detailTab='summary';openDetail(b.dataset.detailAction)});document.querySelectorAll('[data-sales]').forEach(b=>b.onclick=async()=>{state.detailTab='orders';openDetail(b.dataset.lead);await RTSales.mount(leads.find(l=>l.id===b.dataset.lead));b.dataset.sales==='order'?RTSales.order():RTSales.payment()});document.querySelectorAll('[data-misleading]').forEach(b=>b.onclick=()=>{const l=leads.find(x=>x.id===b.dataset.misleading);RTSales.formDialog('🗑 Report as Misleading',`<p>该地址将移至 Delisted，并永久排除后续导入。</p><label>原因<textarea name="reason" required maxlength="1000"></textarea></label>`,async f=>{await RTCRM.remove(l,f.get('reason'));detailDirty=false;$('detail').close();render()})})}
 function footer(l){let foot=$('detail-actions');if(!foot){foot=document.createElement('div');foot.id='detail-actions';$('detail').append(foot)}foot.hidden=false;foot.innerHTML=`${badge(l)}${actions(l,true)}<span id="stage-message" role="status"></span>`;
 bindActions();
 const form=$('slot-form');if(form)form.onsubmit=async event=>{event.preventDefault();const b=event.submitter;b.disabled=true;const f=new FormData(form),slot={weekday:+f.get('weekday'),start:f.get('start'),end:f.get('end'),courts:+f.get('courts'),from:f.get('from'),until:f.get('until')};try{await RTCRM.saveSlots(l.id,[...RTCRM.slots(l.id),slot]);render();openDetail(l.id)}catch(e){$('slot-message').textContent=e.message;b.disabled=false}};
 document.querySelectorAll('[data-delete-slot]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await RTCRM.saveSlots(l.id,RTCRM.slots(l.id).filter((_,i)=>i!==+b.dataset.deleteSlot));render();openDetail(l.id)}catch(e){b.disabled=false;$('stage-message').textContent=e.message}});
 }
 function delisted(){return `<h2>🗑 Delisted</h2><div class="cards">${RTCRM.exclusions.map(x=>`<article class="card"><h3>${esc(leads.find(l=>l.id===x.id)?.name||x.id)}</h3><p>${esc(x.address)}</p><small>已永久排除该地址</small>${RTCRM.canEdit?`<p>${esc(x.reason||'')}</p>`:''}</article>`).join('')||'<p>暂无已移除线索</p>'}</div>`}
 function calendar(ls){const [y,m]=month.split('-').map(Number),n=new Date(Date.UTC(y,m,0)).getUTCDate(),off=(new Date(Date.UTC(y,m-1,1)).getUTCDay()+6)%7;return `<div class="monthbar"><button data-month="-1">←</button><strong>${esc(month)}</strong><button data-month="1">→</button><span>固定档期 · Melbourne</span></div><div class="calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div>${d}</div>`).join('')}${'<div class="day muted"></div>'.repeat(off)}${Array.from({length:n},(_,i)=>{const date=month+'-'+String(i+1).padStart(2,'0'),weekday=new Date(date+'T12:00:00Z').getUTCDay();return `<div class="day">${i+1}${ls.filter(l=>status(l)==='client').flatMap(l=>RTCRM.slots(l.id).filter(s=>s.weekday===weekday&&s.from<=date&&(!s.until||s.until>=date)).map(s=>`<button data-id="${esc(l.id)}"><strong>${esc(l.name)}</strong><small>${esc(s.start)}–${esc(s.end)} · ${s.courts} 场</small></button>`)).join('')}</div>`}).join('')}</div><p class="calendar-note">预订系统：待接入</p>`}
 function reports(){const all=leads.filter(l=>l.role!=='Competition reference'&&RTCRM.visible(l)&&l.scope==='inside'),types={};all.forEach(l=>types[l.type]=(types[l.type]||0)+1);const group=Object.keys(statuses).filter(k=>k!=='excluded').map(k=>[k,all.filter(l=>status(l)===k).length]);return `<div class="report-grid"><section class="report-panel"><h2>客户进展</h2><div class="pipeline-bars">${group.map(([k,n])=>`<div><span>${statuses[k].label}</span><strong>${n}</strong><div class="bar-track"><i class="bar-${k}" style="width:${100*n/Math.max(1,all.length)}%"></i></div></div>`).join('')}</div><p class="muted">10 公里内 · 当前状态</p></section><section class="report-panel"><h2>联系资料</h2>${[['邮箱',0],['电话',1],['官网',4]].map(([label,i])=>{const n=all.filter(l=>RTCRM.routes(l)[i].url).length;return `<div class="report-measure"><span>${label}</span><strong>${n} <small>/ ${all.length}</small></strong><progress max="${Math.max(1,all.length)}" value="${n}"></progress></div>`}).join('')}</section><section class="report-panel wide"><h2>线索类型</h2><div class="type-bars">${Object.entries(types).sort((a,b)=>b[1]-a[1]).map(([t,n])=>`<div><span>${esc(t)}</span><div class="bar-track"><i style="width:${n/Math.max(...Object.values(types))*100}%"></i></div><strong>${n}</strong></div>`).join('')}</div></section><section class="report-panel"><h2>客户固定档期</h2><strong class="report-big">${all.filter(l=>status(l)==='client').reduce((n,l)=>n+RTCRM.slots(l.id).length,0)}</strong><p>每周档期规则</p></section><section class="report-panel"><h2>预订与收入</h2><strong class="report-big">—</strong><p>待接入预订系统</p></section></div>`}
 return {status,badge,summary,schedules,footer,calendar,reports,actions,bindActions,delisted};
})();
render=function(){if(!D)return;workspaceStatus();let ls=filtered();if(section==='Clients')ls=ls.filter(l=>RTFlow.status(l)==='client');else if(section==='Followup')ls=ls.filter(l=>['follow','hold','giveup'].includes(RTFlow.status(l)));else if(section==='Leads')ls=ls.filter(l=>RTFlow.status(l)==='new');
 $('title').textContent=section;$('intro').hidden=true;document.querySelectorAll('#nav button').forEach(b=>{b.classList.toggle('active',b.dataset.section===section);b.setAttribute('aria-current',b.dataset.section===section?'page':'false')});const all=leads.filter(l=>RTCRM.visible(l)&&l.scope==='inside'&&l.role!=='Competition reference');$('stats').innerHTML=[[all.filter(l=>RTFlow.status(l)==='new').length,'尚未跟进'],[all.filter(l=>RTFlow.status(l)==='follow').length,'跟进中'],[all.filter(l=>RTFlow.status(l)==='client').length,'已合作'],[RTCRM.excludedCount,'已排除地址']].map(([n,t])=>`<div class="stat"><strong>${n}</strong><span>${t}</span></div>`).join('');$('controls').hidden=['Channels','Reports','Delisted'].includes(section);$('export').hidden=['Channels','Reports','Delisted'].includes(section);$('views').innerHTML='';const views=section==='Clients'?['Map','Calendar','List']:['Map','List','Everything'];if(!views.includes(view))view=views[0];if(!['Channels','Reports','Delisted'].includes(section))for(const v of views){const b=document.createElement('button');b.textContent=v;b.classList.toggle('selected',view===v);b.onclick=()=>{view=v;sync();render()};$('views').append(b)}if(section==='Leads'||section==='Channels'){const b=document.createElement('button');b.className='channel-jump';b.textContent=section==='Leads'?'Channels ↗':'← Leads';b.onclick=()=>{section=section==='Leads'?'Channels':'Leads';sync();render()};$('views').append(b)}$('count').textContent=ls.length+' 条';if(section==='Clients'){for(const [label,mode] of [['发票设置','settings'],['预览发票模板','sample']]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>RTSales.globalInvoice(mode);$('views').append(b)}}
 const stageRows=ls; if(section==='Followup'&&state.followStage&&state.followStage!=='all')ls=ls.filter(l=>RTFlow.status(l)===state.followStage);
 if(section==='Delisted'){$('content').innerHTML=RTFlow.delisted();$('count').textContent=RTCRM.excludedCount+' 条'}else if(section==='Channels'){$('content').innerHTML=channelsView();$('count').textContent=''}else if(section==='Reports'){$('content').innerHTML=RTFlow.reports();$('count').textContent=''}else if(view==='Calendar')$('content').innerHTML=RTFlow.calendar(ls);else if(!ls.length)$('content').innerHTML='<div class="empty"><h3>'+({Clients:'暂无已合作客户',Followup:'暂无跟进客户'}[section]||'暂无匹配线索')+'</h3></div>';else if(view==='Map')$('content').innerHTML=mapView(ls);else if(view==='Everything')$('content').innerHTML=`<div class="cards">${ls.map(card).join('')}</div>`;else $('content').innerHTML=table(ls);
 if(section==='Followup'){const container=document.createElement('div');container.className='stage-filters';container.innerHTML=[['all','全部'],['follow','跟进中'],['hold','On hold'],['giveup','Give up']].map(([k,t])=>`<button data-stage-filter="${k}" class="${(state.followStage||'all')===k?'selected':''}">${t} · ${stageRows.filter(l=>k==='all'||RTFlow.status(l)===k).length}</button>`).join('');$('content').prepend(container);container.querySelectorAll('button').forEach(b=>b.onclick=()=>{state.followStage=b.dataset.stageFilter;render()})}
 if(view==='Map'&&!['Channels','Reports','Delisted'].includes(section)&&ls.length){const located=ls.filter(l=>l.lat!=null&&l.lon!=null);if(located.length)RTMaps.draw({element:$('google-map'),rows:located,center:D.center,onSelect:highlightMap,onDetail:openDetail});if($('fit-map'))$('fit-map').onclick=()=>RTMaps.fit()}
 bindWorkspace();$('content').querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openDetail(b.dataset.id));$('content').querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>{resetFields();$('channel').value=b.dataset.channel;section='Leads';view='List';sync();render()});$('content').querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{highlightMap(b.dataset.map);RTMaps.select(b.dataset.map)});$('content').querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{const [y,m]=month.split('-').map(Number),d=new Date(Date.UTC(y,m-1+Number(b.dataset.month),1));month=d.toISOString().slice(0,7);sync();render()});
};
